entries[71899] = { ["name"] = "Blutgeschosswirbel", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert einen Blitz von dunklem Blut auf das Ziel, wobei das Ziel und in einem Umkreis von 0a1 Metern befindliche Verbündete 16150 to 17850 Schaden erleiden." }
entries[71903] = { ["name"] = "Item - Shadowmourne Legendary", ["text"] = "Eure Nahkampfangriffe haben eine Chance, ein Seelenfragment zu entziehen, welches Euch 30 Stärke gewährt. Sobald Ihr 10 Seelenfragmente angesammelt habt, werden sie als Chaosbann entfesselt, der 1900 to 2100 Schattenschaden verursacht, dieser Schaden wird unter allen Zielen innerhalb von 15 Metern aufgeteilt. Zudem werden Euch 10 Sek. lang 270 Stärke gewährt." }
entries[71904] = { ["name"] = "Chaosbann", ["text"] = "20 Meter Reichweite\nSofort\nVerursacht 1900 to 2100 Schattenschaden, der zwischen allen Feinden innerhalb von 15 Metern des Einschlagkraters aufgeteilt wird." }
entries[71905] = { ["name"] = "Seelenfragment", ["text"] = "Sofort\nHat ein Seelenfragment erhalten, dass pro Stück 30 Stärke gewährt. Wenn 10 Seelenfragmente angesammelt wurden, werden sie entfesselt und lösen den Chaosbann aus. Hält 1 Min. lang an." }
entries[71906] = { ["name"] = "Abgetrennte Essenz", ["text"] = "40 Meter Reichweite\nWirken in 1 sek.\nReißt dem Ziel die Seele aus dem Körper. Die dunkle Seite der Seele bildet ein geisterhaftes Wesen, das dem Willen des Zaubernden unterworfen ist. Hält bis Abbruch lang an." }
entries[71909] = { ["name"] = "Herzbrecher", ["text"] = "5 Meter Reichweite\nSofort\nDiese seltsame experimentelle Gerätschaft war eigentlich dafür gedacht, den Brustkorb des Ziels inmitten einer Blutfontäne zu sprengen. Stattdessen löst sie einen kurzen, aber nichtdestotrotz bemitleidenswerten, Anfall von kläglichen, herzzerreißenden Schluchzern aus." }
entries[71910] = { ["name"] = "Strange Tentacle: Base Effect" }
entries[71911] = { ["name"] = "Schattenresonanz", ["text"] = "Sofort\nDas nächste Ziel hallt mit Schattenenergie wider, wodurch es 1000 Schaden erleidet und sein erlittener Schattenschaden aus allen Quellen um 35% verringert wird. Hält bis Abbruch lang an." }
