entries[71924] = { ["name"] = "Seuchenstoß", ["text"] = "Nahkampfreichweite\nSofort\nEin bösartiger Schlag, der 60% Waffenschaden plus 27 verursacht und das Ziel mit Blutseuche infiziert, einer Krankheit die im Verlauf der Zeit Schattenschaden verursacht. Der Schlag entfernt einen Effekt, der Heilung über Zeit hervorruft." }
entries[71925] = { ["name"] = "Zerfleischen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nZerfleischt das Ziel, verursacht 100% des normalen Schadens plus 25 und lässt es 12 Sek. lang 30% zusätzlichen Schaden durch 'Zermalmen', 'Schreddern' und Blutungseffekte erleiden. Gewährt 1 Combopunkt." }
entries[71926] = { ["name"] = "Zerfetzen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden über Zeit verursacht." }
entries[71927] = { ["name"] = "Schießen", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nBenötigt Distanzwaffe\nSchießt auf den Feind und fügt körperlichen Schaden zu." }
entries[71928] = { ["name"] = "Feuerball", ["text"] = "40 Meter Reichweite\nWirken in 3 sek.\nFügt einem Gegner Feuerschaden zu." }
entries[71929] = { ["name"] = "Frostnova", ["text"] = "Sofort\nVerursacht Frostschaden bei in der Nähe befindlichen Feinden und macht sie bis zu 5 Sek. lang bewegungsunfähig." }
entries[71930] = { ["name"] = "Lichtblitz", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nRuft heilige Magie herbei, um einen Verbündeten zu heilen." }
entries[71931] = { ["name"] = "Große Heilung", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nRuft heilige Magie herbei, um einen Verbündeten zu heilen." }
entries[71932] = { ["name"] = "Erneuerung", ["text"] = "40 Meter Reichweite\nSofort\nHeilt das Ziel im Verlauf von 15 Sek. um 23565 to 26435." }
entries[71933] = { ["name"] = "Ausweiden", ["text"] = "Nahkampfreichweite\nSofort\nFinishing-Move, der Schaden verursacht." }
entries[71934] = { ["name"] = "Blitzschlag", ["text"] = "30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 2334 to 2666 Naturschaden zu." }
entries[71935] = { ["name"] = "Gewitter", ["text"] = "Sofort\nIhr ruft einen Blitzschlag hernieder, der allen Feinden im Umkreis von 0 Metern Schaden zufügt. Alle in der Nähe befindlichen Feinde erleiden 1850 to 2150 Naturschaden und werden zurückgestoßen." }
entries[71936] = { ["name"] = "Schattenblitz", ["text"] = "40 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht Schattenschaden." }
entries[71937] = { ["name"] = "Verderbnis", ["text"] = "30 Meter Reichweite\nSofort\nVerderbt in der Nähe befindliche Feinde und fügt ihnen so 24 Sek. lang alle 3 Sek. Schattenschaden zu." }
entries[71938] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an und verursacht (Attack power * 1414 / 100) Schaden. Zusätzlich stellen die nächsten 3 erfolgreichen Nahkampfangriffe 1.5% der maximalen Gesundheit wieder her. Dieser Effekt hält 8 Sek. an. Der verursachte Schaden basiert auf Eurer Angriffskraft." }
entries[71939] = { ["name"] = "Alptraumwolke" }
entries[71940] = { ["name"] = "Schreckliche Alpträume", ["text"] = "Unbegrenzte Reichweite\nSofort\nLässt das Ziel Alpträume erleiden, die pro Sekunde 200 Naturschaden verursachen. Zusätzlich regeneriert das Ziel alle 3 Sek. 200 Mana. Der Schaden und die Heilung des Ziels werden ebenfalls um 10% erhöht. Bis zu 100-mal stapelbar. Hält 40 Sek. lang an." }
entries[71941] = { ["name"] = "Schreckliche Alpträume", ["text"] = "Unbegrenzte Reichweite\nSofort\nLässt das Ziel Alpträume erleiden, die pro Sekunde 200 Naturschaden verursachen. Zusätzlich regeneriert das Ziel alle 3 Sek. 200 Mana. Der Schaden und die Heilung des Ziels werden ebenfalls um 10% erhöht. Bis zu 100-mal stapelbar. Hält 40 Sek. lang an." }
entries[71943] = { ["name"] = "Schattenresonanz", ["text"] = "Sofort\nBeschwört einen dunklen Kern. Dunkle Kerne nähren sich von ihrer eignen Energie, wodurch sie sich nach gewisser Zeit selbst zerstören." }
entries[71944] = { ["name"] = "Schockvortex", ["text"] = "Sofort\nFügt allen Feinden innerhalb von 12 Metern 12000 Schaden zu und stößt sie zurück." }
entries[71945] = { ["name"] = "Schockvortex" }
entries[71946] = { ["name"] = "Alpträume", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt Valithria Traumwandler pro Sekunde 8000 Naturschaden zu." }
