entries[71951] = { ["name"] = "Nekrotischer Stoß", ["text"] = "Nahkampfreichweite\nSofort\nTrifft den Feind mit einer verfluchten Klinge, fügt dem Ziel 4625 to 5375 körperlichen Schaden und eine andauernde Krankheit zu, die die nächste erhaltene Heilung in Höhe von 15000 negiert." }
entries[71952] = { ["name"] = "Präsenz der Sinistren" }
entries[71953] = { ["name"] = "Leuchtende Aura", ["text"] = "Sofort\nDer Paladin erglänzt in strahlendem Licht und heilt nahe Verbündete alle 3 Sek. um 3% ihrer maximalen Gesundheit." }
entries[71954] = { ["name"] = "Heiliger Champion", ["text"] = "45 Meter Reichweite\nSofort\nLegt das Ziel als den Champion des Priesters fest und gewährt ihm 30 Min. lang zusätzliche Gesundheit und Schaden." }
entries[71955] = { ["name"] = "Fokussierte Angriffe", ["text"] = "30 Meter Reichweite\nSofort\nSpringt 30 Sek. lang auf den Rücken des Ziels, was die Angriffsgeschwindigkeit erhöht, es aber unmöglich macht, ein anderes Ziel anzugreifen." }
entries[71956] = { ["name"] = "Erfrischender Regen", ["text"] = "200 Mana\nKanalisiert (Wirken in 10 sek.)\nRegeneriert 10 Sek. lang alle nahen Gruppenmitglieder alle 2 Sek. um 13875 to 16125. Kanalisiert." }
entries[71958] = { ["name"] = "Präsenz der Sinistren", ["text"] = "Sofort\nDie Anwesenheit von anderen Vampyren stärkt Blutkönigin Lana'thel und erhöht die Macht ihres Zaubers 'Umhüllung der Trauer' um 10%." }
entries[71959] = { ["name"] = "Präsenz der Sinistren", ["text"] = "Sofort\nDie Anwesenheit von anderen Vampyren stärkt Blutkönigin Lana'thel und erhöht die Macht ihres Zaubers 'Umhüllung der Trauer' um 10%." }
entries[71960] = { ["name"] = "Heldenhafter Sprung", ["text"] = "Unbegrenzte Reichweite\nSofort\nSpringt durch die Luft und schmettert auf alle Feinde im Umkreis von 8 Metern um das Zielgebiet hinab, verursacht Schaden und betäubt sie 2 Sek. lang." }
entries[71961] = { ["name"] = "Heldenhafter Sprung", ["text"] = "8 - 25 Meter Reichweite\nSofort 45 sek. Abklingzeit\nSpringt durch die Luft und schmettert auf alle Feinde im Umkreis von 8 Metern um das Zielgebiet hinab und betäubt sie 0.10 Sek. lang." }
entries[71965] = { ["name"] = "Regen des Chaos", ["text"] = "50 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nLässt einen Schmelzregen niedergehen, der alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. 142 to 157 Chaosschaden zufügt." }
